function parseArray(str) {
  var parts = String(str).split(/[\s,;]+/), out = [];
  for (var i = 0; i < parts.length; i++) {
    if (!parts[i]) continue;
    var v = Number(parts[i]);
    if (!isFinite(v)) continue;
    if (v < 0) v = 0;
    if (v >= 1) v = 0.999;
    out.push(v);
  }
  return out;
}

