function bsCheck(buckets) {
  var bad = {}, problems = [], flat = [], b, k;
  for (b = 0; b < 10; b++) for (k = 0; k < buckets[b].length; k++) flat.push(buckets[b][k]);
  var a = bsA.slice().sort(cmpNum), g = flat.slice().sort(cmpNum);
  var msOk = a.length === g.length;
  if (msOk) for (var i = 0; i < a.length; i++) if (Math.abs(a[i] - g[i]) > 1e-9) { msOk = false; break; }
  if (!msOk) problems.push('B does not hold exactly the values of A (' + g.length + ' placed, ' + a.length + ' expected)');
  for (b = 0; b < 10; b++) {
    for (k = 0; k < buckets[b].length; k++) {
      var x = buckets[b][k];
      if (Math.floor(10 * x) !== b) {
        bad[b + ':' + k] = 1;
        problems.push(bsFmt(x) + ' sits in bucket ' + b + ' but floor(10x) = ' + Math.floor(10 * x));
      }
      if (k > 0 && buckets[b][k - 1] > x + 1e-12) {
        bad[b + ':' + k] = 1; bad[b + ':' + (k - 1)] = 1;
        problems.push('bucket ' + b + ' chain out of order: ' + bsFmt(buckets[b][k - 1]) + ' before ' + bsFmt(x));
      }
    }
  }
  return { ok: msOk && problems.length === 0, bad: bad, problems: problems };
}

