    finishRun({ frames: [{ kind: 'error', state: emptyBuckets(), indices: null, read: 0, mark: -1, message: 'ERROR: ' + (e.message || 'worker failed') }], error: 'worker' });
  };
  w.onmessage = function (e) {
    if (done) return; done = true; clearTimeout(timer); cleanup();
