}
function pbPlay() {
  if (!bsFrames.length) return;
  if (bsPlaying) { pbStop(); return; }
  if (bsIdx >= bsFrames.length - 1) bsIdx = -1;
  bsPlaying = true;
  document.getElementById('pbPlayBtn').textContent = '⏸';
  bsTimer = setInterval(function () {
    if (bsIdx >= bsFrames.length - 1) { pbStop(); return; }
    showFrame(bsIdx + 1);
  }, 1000 / bsFps);
}
function setSpeed(v) {
  bsFps = Math.max(1, v);
