<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ────────── geometry / palette ────────── */
var VBW = 1060, VBH = 880;
var bsDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
bsDraw.viewbox(0, 0, VBW, VBH);
var gStatic = bsDraw.group();
var gMain = bsDraw.group();

var LA = { x: 74, w: 78 }, LB = { x: 300, w: 78 };
var Y0 = 52, CH = 58;
var NLy = 736, NLx0 = 300, NLx1 = 940, NLw = NLx1 - NLx0;
var SERIF = '"Times New Roman", Georgia, serif';

var COL = {
  gray: '#d9d9d9', line: '#000',
  amber: '#e08a00', amberFill: '#ffe0a8',
  blue: '#2f6fb5', blueFill: '#bcd9f5', blueSoft: '#dceaf8',
  red: '#c02626', redFill: '#ffc9c9'
};

/* ────────── state ────────── */
var bsA = [.78, .17, .39, .26, .72, .94, .21, .12, .23, .68];
var bsView = { buckets: null, read: 0, mark: -1, hi: null, bad: {}, concat: false, probe: 0.94 };
var bsCount = 10;
var bsFrames = [], bsIdx = -1, bsPlaying = false, bsTimer = null, bsFps = 4, bsBad = {}, bsReplay = false;

function bsFmt(x) { var s = Number(x).toFixed(2); return s.charAt(0) === '0' ? s.slice(1) : s; }
function cmpNum(a, b) { return a - b; }

function emptyBuckets() { var o = []; for (var i = 0; i < 10; i++) o.push([]); return o; }

function distributeState(count) {
  var bs = emptyBuckets(), last = null;
  for (var i = 0; i < count && i < bsA.length; i++) {
    var x = bsA[i], b = Math.max(0, Math.min(9, Math.floor(10 * x))), k = 0;
    while (k < bs[b].length && bs[b][k] < x) k++;
    bs[b].splice(k, 0, x);
    last = { b: b, k: k };
  }
  return { buckets: bs, last: last };
}

/* ────────── drawing helpers ────────── */
function bsLabel(g, str, x, y, size, o) {
  o = o || {};
  var t = g.plain(String(str));
  t.font({ family: SERIF, size: size });
  if (o.italic) t.font({ style: 'italic' });
  t.attr({
    x: x, y: y, 'text-anchor': o.anchor || 'middle',
    'dominant-baseline': 'central', fill: o.fill || '#111', 'pointer-events': 'none'
  });
  if (o.halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3.5, 'stroke-linejoin': 'round' });
  return t;
}
function bsArrow(g, x1, y, x2, color, w) {
  color = color || '#000'; w = w || 2.4;
  g.line(x1, y, x2 - 9, y).stroke({ color: color, width: w });
  g.polygon([[x2, y], [x2 - 12, y - 6.5], [x2 - 12, y + 6.5]]).fill(color);
}
function hook(el, tip, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', hideTooltip);
  el.on('click', function () { showPopup(title, body); });
}

/* ────────── static layer ────────── */
bsLabel(gStatic, 'A', LA.x + LA.w / 2, 30, 30, { italic: true });
bsLabel(gStatic, 'B', LB.x + LB.w / 2, 30, 30, { italic: true });
bsLabel(gStatic, '(a)', LA.x + LA.w / 2, 676, 28);
bsLabel(gStatic, '(b)', 640, 676, 28);

/* ────────── main render ────────── */
function bsRender() {
  gMain.clear();
  var v = bsView, n = bsA.length;
  var chA = Math.min(CH, 580 / Math.max(10, n));

  /* ---- panel (a) ---- */
  for (var i = 0; i < n; i++) {
    var y = Y0 + i * chA, hot = (v.read === i + 1);
    var r = gMain.rect(LA.w, chA).move(LA.x, y)
      .fill(hot ? COL.amberFill : COL.gray)
      .stroke({ color: hot ? COL.amber : COL.line, width: hot ? 3.5 : 2 });
    bsLabel(gMain, bsFmt(bsA[i]), LA.x + LA.w / 2, y + chA / 2, 26);
    bsLabel(gMain, String(i + 1), LA.x - 14, y + chA / 2, 22, { anchor: 'end' });
    (function (idx) {
      var x = bsA[idx], b = Math.floor(10 * x);
      hook(r, 'A[' + (idx + 1) + '] = ' + bsFmt(x) + '  →  floor(10 × ' + bsFmt(x) + ') = bucket ' + b,
        'A[' + (idx + 1) + '] = ' + bsFmt(x),
        'Bucket sort reads this value once and computes floor(10·x) = ' + b + '. That single arithmetic step decides the coarse position of the value in the final order — no comparison with any other element of A is needed.');
    })(i);
  }

  /* ---- chain layout ---- */
  var maxLen = 1, b;
  for (b = 0; b < 10; b++) maxLen = Math.max(maxLen, v.buckets[b].length);
  var NWv = 66, NWp = 46, NH = 40, startX = 452, spacing = 196;
  if (maxLen > 3) {
    NWv = 50; NWp = 34; NH = 34;
    spacing = Math.max(92, (1038 - startX - (NWv + NWp)) / (maxLen - 1));
  }

  var probeB = Math.max(0, Math.min(9, Math.floor(10 * v.probe)));

  /* ---- panel (b) ---- */
  for (b = 0; b < 10; b++) {
    var by = Y0 + b * CH, cy = by + CH / 2;
    var marked = (v.mark === b);
    var cell = gMain.rect(LB.w, CH).move(LB.x, by)
      .fill(marked ? COL.blueFill : COL.gray)
      .stroke({ color: marked ? COL.blue : COL.line, width: marked ? 3.5 : 2 });
    bsLabel(gMain, String(b), LB.x - 14, cy, 22, { anchor: 'end' });
    if (probeB === b) {
      gMain.rect(LB.w + 12, CH + 10).move(LB.x - 6, by - 5).fill('none')
        .stroke({ color: COL.blue, width: 2, dasharray: '5,4' });
    }
    (function (bb) {
      var list = v.buckets[bb].map(bsFmt).join(' → ') || 'NIL (empty)';
      hook(cell, 'B[' + bb + ']  interval [' + (bb / 10).toFixed(1) + ', ' + ((bb + 1) / 10).toFixed(1) + ')   chain: ' + list,
        'Bucket ' + bb,
        'B[' + bb + '] is the head of a linked list holding every x with floor(10·x) = ' + bb + ', i.e. x in the half-open interval [' + (bb / 10).toFixed(1) + ', ' + ((bb + 1) / 10).toFixed(1) + '). Its current chain is ' + list + '. Because buckets are visited in index order at the end, everything here comes after every value in buckets 0…' + (bb - 1) + ' and before everything in buckets ' + (bb + 1) + '…9.');
    })(b);

    var list = v.buckets[b];
    if (!list.length) {
      gMain.line(LB.x + 12, by + CH - 11, LB.x + LB.w - 12, by + 11).stroke({ color: COL.line, width: 2.2 });
      continue;
    }
    gMain.line(LB.x + 20, cy, LB.x + LB.w, cy).stroke({ color: COL.line, width: 2.4 });
    bsArrow(gMain, LB.x + LB.w, cy, startX, COL.line, 2.4);

    for (var k = 0; k < list.length; k++) {
      var nx = startX + k * spacing, ny = cy - NH / 2;
      var isHi = v.hi && v.hi.b === b && v.hi.k === k;
      var isBad = !!v.bad[b + ':' + k];
      var fill = isBad ? COL.redFill : (isHi ? COL.blueFill : COL.gray);
      var strk = isBad ? COL.red : (isHi ? COL.blue : COL.line);
      var box = gMain.rect(NWv + NWp, NH).move(nx, ny)
        .fill(fill).stroke({ color: strk, width: (isHi || isBad) ? 3.2 : 2 });
      gMain.line(nx + NWv, ny, nx + NWv, ny + NH).stroke({ color: strk, width: 2 });
      bsLabel(gMain, bsFmt(list[k]), nx + NWv / 2, cy, NH > 36 ? 25 : 20);
      if (k < list.length - 1) {
        gMain.line(nx + NWv + 11, cy, nx + NWv + NWp - 11, cy).stroke({ color: COL.line, width: 2.6 });
        bsArrow(gMain, nx + NWv + NWp, cy, nx + spacing, COL.line, 2.4);
      } else {
        gMain.line(nx + NWv + 8, ny + NH - 7, nx + NWv + NWp - 8, ny + 7).stroke({ color: COL.line, width: 2.2 });
      }
      (function (bb, kk, val, badFlag) {
        hook(box, 'node ' + kk + ' of bucket ' + bb + ' = ' + bsFmt(val) + (badFlag ? '  ✗ violates the invariant' : ''),
          'Record ' + bsFmt(val),
          'A two-field record: the left field stores the key ' + bsFmt(val) + ', the right field stores the next pointer (a diagonal slash means NIL). It sits at position ' + kk + ' of bucket ' + bb + ' because insertion walks the tiny chain and splices the node where the list stays increasing.' + (badFlag ? ' This node breaks the invariant — it is either in the wrong bucket or out of order in its chain.' : ''));
      })(b, k, list[k], isBad);
    }
  }

  /* ---- number line ---- */
  if (v.mark >= 0 && v.mark !== probeB) {
    gMain.rect(NLw / 10, 28).move(NLx0 + v.mark * NLw / 10, NLy - 14).fill(COL.blueSoft);
  }
  gMain.rect(NLw / 10, 28).move(NLx0 + probeB * NLw / 10, NLy - 14)
    .fill(COL.blueFill).stroke({ color: COL.blue, width: 1.6, dasharray: '4,3' });
  gMain.line(NLx0, NLy, NLx1, NLy).stroke({ color: '#444', width: 2 });
  for (var t = 0; t <= 10; t++) {
    var tx = NLx0 + t * NLw / 10;
    gMain.line(tx, NLy - 9, tx, NLy + 9).stroke({ color: '#444', width: 1.6 });
    if (t < 10) bsLabel(gMain, String(t), tx + NLw / 20, NLy + 24, 14, { fill: '#666' });
  }
  bsLabel(gMain, '0', NLx0, NLy + 24, 16, { fill: '#333' });
  bsLabel(gMain, '1', NLx1, NLy + 24, 16, { fill: '#333' });
  var px = NLx0 + v.probe * NLw;
  gMain.line(px, NLy - 24, px, NLy + 14).stroke({ color: COL.blue, width: 2.2 });
  gMain.polygon([[px, NLy - 12], [px - 7, NLy - 24], [px + 7, NLy - 24]]).fill(COL.blue);
  var lx = Math.max(NLx0 + 60, Math.min(NLx1 - 60, px));
  bsLabel(gMain, 'x = ' + bsFmt(v.probe) + '  →  ⌊10x⌋ = ' + probeB, lx, NLy - 40, 19,
    { fill: COL.blue, halo: true });
  var nlHit = gMain.rect(NLw, 60).move(NLx0, NLy - 26).fill('#fff').opacity(0);
  hook(nlHit, 'each interval is half-open: [b/10, (b+1)/10)',
    'The half-open partition',
    'floor(10·x) cuts [0,1) into ten intervals [b/10, (b+1)/10). The left endpoint belongs to the bucket, the right endpoint belongs to the next one — that is why 0.9 through 0.999 all land in bucket 9 and .94 can never spill into a tenth bucket.');

  /* ---- concatenated output ---- */
  if (v.concat) {
    var flat = [];
    for (b = 0; b < 10; b++) for (var q = 0; q < v.buckets[b].length; q++) flat.push({ v: v.buckets[b][q], b: b });
    if (flat.length) {
      var cw = Math.min(62, 620 / flat.length), oy = 800, ox = 300;
      bsLabel(gMain, 'B[0] ⧺ B[1] ⧺ … ⧺ B[9] :', ox - 6, oy + 18, 17,
        { anchor: 'end', italic: true, fill: COL.blue });
      for (var m = 0; m < flat.length; m++) {
        var bad = (m > 0 && flat[m - 1].v > flat[m].v + 1e-12);
        var cr = gMain.rect(cw, 36).move(ox + m * cw, oy)
          .fill(bad ? COL.redFill : COL.blueFill)
          .stroke({ color: bad ? COL.red : COL.blue, width: 1.8 });
        bsLabel(gMain, bsFmt(flat[m].v), ox + m * cw + cw / 2, oy + 18, cw > 50 ? 20 : 15);
        (function (item, bad2) {
          hook(cr, bsFmt(item.v) + ' came from bucket ' + item.b + (bad2 ? ' — out of order!' : ''),
            'Concatenation', 'Walking buckets 0…9 head-to-tail emits ' + bsFmt(item.v) + ' here. No comparison is ever made between elements of different buckets: the index floor(10x) already ordered them.');
        })(flat[m], bad);
      }
    }
  }
}

/* ────────── interaction: probe slider ────────── */
function update_probeValue(v) {
  bsView.probe = v;
  bsRender();
}

/* ────────── interaction: concat toggle ────────── */
function toggle_concat(on) { bsView.concat = !!on; bsRender(); }

/* ────────── interaction: distribution pass ────────── */
function setDistrib(count, showLast) {
  bsReplay = false; pbStop();
  bsCount = Math.max(0, Math.min(bsA.length, count));
  var d = distributeState(bsCount);
  bsView.buckets = d.buckets; bsView.bad = {};
  if (showLast && d.last) { bsView.read = bsCount; bsView.mark = d.last.b; bsView.hi = d.last; }
  else { bsView.read = 0; bsView.mark = -1; bsView.hi = null; }
  var st = bsCount === 0 ? 'idle' : (bsCount >= bsA.length ? 'done' : 'running');
  var el = document.getElementById('distributeStepVal');
  if (el) el.textContent = st + ' — ' + bsCount + ' of ' + bsA.length + ' placed';
  bsRender();
}
function trigger_distributeReset() { setDistrib(0, false); }
function trigger_distributeStep() { setDistrib(bsCount + 1, true); }
function trigger_distributeRun() { setDistrib(bsA.length, false); }

/* ────────── demo steps ────────── */
var bsSteps = [
  {
    title: 'The unsorted input, distributed',
    narration: 'Panel (a) holds ten numbers drawn from [0,1) in arbitrary order. Panel (b) is the bucket structure: ten buckets, each the head of a linked list (a diagonal slash means NIL). Step forward to rebuild it one element at a time.',
    st: { count: 10, probe: 0.94, concat: false, read: 0, mark: -1, hi: null }
  },
  {
    title: 'One element, one bucket',
    narration: 'A[1] = .78 is read, floor(10 × .78) = 7 highlights bucket 7 and its interval [0.7, 0.8), and a new node is drawn on that chain.',
    st: { count: 1, probe: 0.78, concat: false, read: 1, mark: 7, hi: { b: 7, k: 0 } }
  },
  {
    title: 'Insertion keeps each chain sorted',
    narration: 'When .12 (A[8]) arrives after .17, it is spliced ahead of it rather than appended, so bucket 1 reads .12 → .17. Each chain stays sorted as it grows.',
    st: { count: 8, probe: 0.12, concat: false, read: 8, mark: 1, hi: { b: 1, k: 0 } }
  },
  {
    title: 'The half-open convention',
    narration: 'Drag the probe across a bucket boundary: at x = 0.9 the value jumps into bucket 9 and stays there all the way to 0.999, so .94 can never spill into a tenth bucket.',
    st: { count: 10, probe: 0.94, concat: false, read: 0, mark: 9, hi: null }
  },
  {
    title: 'Concatenate in index order',
    narration: 'All ten values are distributed; reading buckets 0 through 9 head-to-tail gives .12 .17 .21 .23 .26 .39 .68 .72 .78 .94 — the sorted output, with no comparison between buckets ever needed.',
    st: { count: 10, probe: 0.5, concat: true, read: 0, mark: -1, hi: null }
  }
];
var bsStep = 0;

function applyStep(i) {
  bsStep = Math.max(0, Math.min(bsSteps.length - 1, i));
  var s = bsSteps[bsStep], st = s.st;
  bsReplay = false; pbStop();
  bsA = [.78, .17, .39, .26, .72, .94, .21, .12, .23, .68];
  bsCount = st.count;
  var d = distributeState(bsCount);
  bsView.buckets = d.buckets; bsView.bad = {};
  bsView.read = st.read; bsView.mark = st.mark; bsView.hi = st.hi;
  bsView.probe = st.probe; bsView.concat = st.concat;

  var pi = document.getElementById('probeValueInput');
  if (pi) { pi.value = st.probe; document.getElementById('probeValueVal').value = st.probe.toFixed(3); }
  var ci = document.getElementById('concatInput'); if (ci) ci.checked = st.concat;
  var ds = document.getElementById('distributeStepVal');
  if (ds) ds.textContent = (bsCount === 0 ? 'idle' : (bsCount >= bsA.length ? 'done' : 'running')) +
    ' — ' + bsCount + ' of ' + bsA.length + ' placed';
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = 'Step ' + (bsStep + 1) + '/' + bsSteps.length + ' · ' + s.title;
  bsRender();
}
function nextStep() { applyStep(bsStep + 1); }
function prevStep() { applyStep(bsStep - 1); }

/* ────────── code workbench ────────── */
var SAMPLES = {
  sample: 'function bucketSort(A, B) {\n  const n = 10;\n  for (let i = 1; i <= n; i++) {\n    const x = read(i);\n    const b = Math.floor(n * x);   // half-open bucket [b/10, (b+1)/10)\n    mark(b);\n    // walk the chain to find the sorted insertion point\n    let k = 0;\n    while (k < listLength(b) && nodeAt(b, k) < x) {\n      k++;\n    }\n    insertAt(b, k, x);\n    note(\'placed \' + x + \' at position \' + k + \' of bucket \' + b);\n  }\n}',
  buggy: 'function bucketSort(A, B) {\n  const n = 10;\n  for (let i = 1; i <= n; i++) {\n    const x = read(i);\n    // BUG 1: round() instead of floor() -- .78 lands in bucket 8, not 7\n    const b = Math.round(n * x);\n    mark(b);\n    // BUG 2: always appends at the tail, so a chain can come out unsorted (.17 before .12)\n    insertAt(b, listLength(b), x);\n  }\n}',
  starter: 'function bucketSort(A, B) {\n  const n = 10;\n  for (let i = 1; i <= n; i++) {\n    const x = read(i);\n    // 1. which bucket?   b = ?\n    // 2. where inside the chain?  use listLength(b) / nodeAt(b, k)\n    // 3. insertAt(b, k, x)\n  }\n}'
};
function loadSample(which) {
  document.getElementById('bucketSortEditorCode').value = SAMPLES[which];
  ['Sample', 'Buggy', 'Starter'].forEach(function (nm) {
    var el = document.getElementById('tab' + nm);
    if (el) el.className = (nm.toLowerCase() === which) ? 'active' : '';
  });
}

var WORKER_SRC = [
  'self.onmessage = function(ev){',
  '  var A = ev.data.A, code = ev.data.code, nB = 10;',
  '  var frames = [], buckets = [];',
  '  for (var i=0;i<nB;i++) buckets.push([]);',
  '  var ops = 0, t0 = Date.now(), lastRead = 0, lastMark = -1;',
  '  function fmt(x){ var s = Number(x).toFixed(2); return s.charAt(0)==="0" ? s.slice(1) : s; }',
  '  function snap(){ var o=[]; for(var i=0;i<nB;i++) o.push(buckets[i].slice()); return o; }',
  '  function guard(){',
  '    ops++;',
  '    if (ops > 4000) throw new Error("Operation cap exceeded (4000 API calls) - possible infinite loop.");',
  '    if (frames.length > 800) throw new Error("Frame cap exceeded (800 frames).");',
  '    if (Date.now() - t0 > 1500) throw new Error("Time limit exceeded (1.5 s).");',
  '  }',
  '  function push(kind, ind, msg){ frames.push({kind:kind, state:snap(), indices:ind||null, message:msg, read:lastRead, mark:lastMark}); }',
  '  function chkB(b, who){ b = Math.trunc(Number(b)); if(!(b>=0 && b<nB)) throw new Error(who+"("+b+"): bucket index must be 0.."+(nB-1)); return b; }',
  '  var read = function(i){ guard(); i = Math.trunc(Number(i));',
  '    if(!(i>=1 && i<=A.length)) throw new Error("read("+i+"): A is 1-indexed, valid range 1.."+A.length);',
  '    lastRead = i; push("read", {a:i}, "read A["+i+"] = "+fmt(A[i-1])); return A[i-1]; };',
  '  var listLength = function(b){ b = chkB(b,"listLength"); guard();',
  '    push("probe", {b:b}, "listLength("+b+") = "+buckets[b].length); return buckets[b].length; };',
  '  var nodeAt = function(b,k){ b = chkB(b,"nodeAt"); guard(); k = Math.trunc(Number(k));',
  '    if(!(k>=0 && k<buckets[b].length)) throw new Error("nodeAt("+b+","+k+"): bucket "+b+" has "+buckets[b].length+" node(s)");',
  '    push("compare", {b:b,k:k}, "nodeAt("+b+","+k+") = "+fmt(buckets[b][k])); return buckets[b][k]; };',
  '  var insertAt = function(b,k,x){ b = chkB(b,"insertAt"); guard(); k = Math.trunc(Number(k)); x = Number(x);',
  '    if(!isFinite(x)) throw new Error("insertAt("+b+","+k+",x): x must be a number");',
  '    if(!(k>=0 && k<=buckets[b].length)) throw new Error("insertAt("+b+","+k+"): position must be 0.."+buckets[b].length);',
  '    buckets[b].splice(k,0,x); lastMark = b;',
  '    push("insert", {b:b,k:k}, "insertAt(bucket "+b+", pos "+k+", "+fmt(x)+")"); return null; };',
  '  var mark = function(b){ b = chkB(b,"mark"); guard(); lastMark = b;',
  '    push("mark", {b:b}, "mark bucket "+b+"  -> interval ["+(b/10).toFixed(1)+", "+((b+1)/10).toFixed(1)+")"); return null; };',
  '  var note = function(t){ guard(); push("note", null, String(t)); return null; };',
  '  var err = null;',
  '  try {',
  '    var factory = new Function("read","listLength","nodeAt","insertAt","mark","note",',
  '      "\\"use strict\\";" + code + "\\n; return (typeof bucketSort === \\"function\\") ? bucketSort : null;");',
  '    var fn = factory(read,listLength,nodeAt,insertAt,mark,note);',
  '    if(!fn) throw new Error("No function named bucketSort(A, B) was found - check the entry point name.");',
  '    fn(A.slice(), {});',
  '  } catch(e){ err = (e && e.message) ? e.message : String(e); }',
  '  if (err) frames.push({kind:"error", state:snap(), indices:null, message:"ERROR: "+err, read:lastRead, mark:lastMark});',
  '  else frames.push({kind:"done", state:snap(), indices:null, message:"finished - "+frames.length+" operations recorded", read:0, mark:-1});',
  '  self.postMessage({frames:frames, error:err});',
  '};'
].join('\n');

function parseArray(str) {
  var parts = String(str).split(/[\s,;]+/), out = [];
  for (var i = 0; i < parts.length; i++) {
    if (!parts[i]) continue;
    var v = Number(parts[i]);
    if (!isFinite(v)) continue;
    if (v < 0) v = 0;
    if (v >= 1) v = 0.999;
    out.push(v);
  }
  return out;
}

function setStatus(txt, color) {
  var el = document.getElementById('runStatus');
  el.textContent = txt; el.style.color = color;
}

function bsCheck(buckets) {
  var bad = {}, problems = [], flat = [], b, k;
  for (b = 0; b < 10; b++) for (k = 0; k < buckets[b].length; k++) flat.push(buckets[b][k]);
  var a = bsA.slice().sort(cmpNum), g = flat.slice().sort(cmpNum);
  var msOk = a.length === g.length;
  if (msOk) for (var i = 0; i < a.length; i++) if (Math.abs(a[i] - g[i]) > 1e-9) { msOk = false; break; }
  if (!msOk) problems.push('B does not hold exactly the values of A (' + g.length + ' placed, ' + a.length + ' expected)');
  for (b = 0; b < 10; b++) {
    for (k = 0; k < buckets[b].length; k++) {
      var x = buckets[b][k];
      if (Math.floor(10 * x) !== b) {
        bad[b + ':' + k] = 1;
        problems.push(bsFmt(x) + ' sits in bucket ' + b + ' but floor(10x) = ' + Math.floor(10 * x));
      }
      if (k > 0 && buckets[b][k - 1] > x + 1e-12) {
        bad[b + ':' + k] = 1; bad[b + ':' + (k - 1)] = 1;
        problems.push('bucket ' + b + ' chain out of order: ' + bsFmt(buckets[b][k - 1]) + ' before ' + bsFmt(x));
      }
    }
  }
  return { ok: msOk && problems.length === 0, bad: bad, problems: problems };
}

function runCode() {
  var codeEl = document.getElementById('bucketSortEditorCode');
  var arr = parseArray(document.getElementById('bucketSortEditorInput').value);
  if (!arr.length) { setStatus('✗ input array is empty / unparsable', COL.red); return; }
  bsA = arr;
  pbStop();
  bsReplay = true; bsFrames = []; bsIdx = -1; bsBad = {};
  bsView.buckets = emptyBuckets(); bsView.read = 0; bsView.mark = -1; bsView.hi = null; bsView.bad = {};
  bsRender();
  setStatus('running…', '#8a6d00');
  document.getElementById('runBtn').disabled = true;

  var url = URL.createObjectURL(new Blob([WORKER_SRC], { type: 'text/javascript' }));
  var w = new Worker(url);
  var done = false;
  function cleanup() { try { w.terminate(); } catch (e) { } URL.revokeObjectURL(url); document.getElementById('runBtn').disabled = false; }
  var timer = setTimeout(function () {
    if (done) return; done = true; cleanup();
    finishRun({ frames: [{ kind: 'error', state: emptyBuckets(), indices: null, read: 0, mark: -1, message: 'ERROR: timed out — the worker did not finish within 2 s (infinite loop?)' }], error: 'timeout' });
  }, 2000);
  w.onerror = function (e) {
    if (done) return; done = true; clearTimeout(timer); cleanup();
    finishRun({ frames: [{ kind: 'error', state: emptyBuckets(), indices: null, read: 0, mark: -1, message: 'ERROR: ' + (e.message || 'worker failed') }], error: 'worker' });
  };
  w.onmessage = function (e) {
    if (done) return; done = true; clearTimeout(timer); cleanup();
    finishRun(e.data);
  };
  w.postMessage({ A: bsA.slice(), code: codeEl.value });
}

function finishRun(data) {
  bsFrames = data.frames || [];
  if (!bsFrames.length) bsFrames = [{ kind: 'error', state: emptyBuckets(), indices: null, read: 0, mark: -1, message: 'ERROR: no frames recorded — did your code call any API op?' }];
  var last = bsFrames[bsFrames.length - 1];
  if (data.error) {
    bsBad = {};
    setStatus('✗ error — see caption', COL.red);
  } else {
    var res = bsCheck(last.state);
    bsBad = res.bad;
    if (res.ok) setStatus('✓ correct — buckets concatenate to sorted order', '#1a7a34');
    else setStatus('✗ wrong: ' + (res.problems[0] || 'invariant broken') + (res.problems.length > 1 ? ' (+' + (res.problems.length - 1) + ' more, click)' : ''), COL.red);
    document.getElementById('runStatus').onclick = function () {
      showPopup(res.ok ? 'Success check passed' : 'Success check failed',
        res.ok ? 'Every value of A appears exactly once, each x lies in bucket floor(10x), and every chain is increasing — so concatenating buckets 0…9 yields the fully sorted sequence.'
          : 'Problems found:\n• ' + res.problems.slice(0, 8).join('\n• '));
    };
  }
  bsReplay = true;
  bsIdx = 0;
  showFrame(0);
  bsPlay();
}

function frameKindTag(k) {
  return { read: 'read', probe: 'len', compare: 'cmp', insert: 'INSERT', mark: 'mark', note: 'note', done: 'done', error: 'ERR' }[k] || k;
}

function showFrame(i) {
  if (!bsFrames.length) return;
  bsIdx = Math.max(0, Math.min(bsFrames.length - 1, i));
  var f = bsFrames[bsIdx];
  bsReplay = true;
  bsView.buckets = f.state;
  bsView.read = f.read;
  bsView.mark = f.mark;
  bsView.hi = (f.indices && f.indices.b != null && f.indices.k != null) ? { b: f.indices.b, k: f.indices.k } : null;
  bsView.bad = (bsIdx === bsFrames.length - 1) ? bsBad : {};
  document.getElementById('frameCounter').textContent = (bsIdx + 1) + ' / ' + bsFrames.length;
  document.getElementById('frameCaption').textContent = f.message;
  var lines = [], start = Math.max(0, bsIdx - 25);
  for (var j = start; j <= bsIdx; j++) {
    lines.push((j === bsIdx ? '▸ ' : '  ') + (j + 1) + '  [' + frameKindTag(bsFrames[j].kind) + '] ' + bsFrames[j].message);
  }
  var lg = document.getElementById('runLog');
  lg.textContent = lines.join('\n');
  lg.scrollTop = lg.scrollHeight;
  bsRender();
}
function pbFirst() { pbStop(); showFrame(0); }
function pbPrev() { pbStop(); showFrame(bsIdx - 1); }
function pbNext() { pbStop(); showFrame(bsIdx + 1); }
function pbStop() {
  if (bsTimer) { clearInterval(bsTimer); bsTimer = null; }
  bsPlaying = false;
  var b = document.getElementById('pbPlayBtn'); if (b) b.textContent = '▶';
}
function pbPlay() {
  if (!bsFrames.length) return;
  if (bsPlaying) { pbStop(); return; }
  if (bsIdx >= bsFrames.length - 1) bsIdx = -1;
  bsPlaying = true;
  document.getElementById('pbPlayBtn').textContent = '⏸';
  bsTimer = setInterval(function () {
    if (bsIdx >= bsFrames.length - 1) { pbStop(); return; }
    showFrame(bsIdx + 1);
  }, 1000 / bsFps);
}
function setSpeed(v) {
  bsFps = Math.max(1, v);
  if (bsPlaying) { clearInterval(bsTimer); bsTimer = setInterval(function () { if (bsIdx >= bsFrames.length - 1) { pbStop(); return; } showFrame(bsIdx + 1); }, 1000 / bsFps); }
}

/* ────────── boot ────────── */
loadSample('sample');
bsView.buckets = distributeState(10).buckets;
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

