// @FIGURE_CODE_BEGIN
/* ────────── geometry / palette ────────── */
var VBW = 1060, BASE_H = 830;
var bsDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
bsDraw.viewbox(0, 0, VBW, BASE_H);
var gStatic = bsDraw.group();
var gMain = bsDraw.group();

var LA = { x: 66, w: 80 }, LB = { x: 302, w: 80 };
var Y0 = 62, CH = 68;                       // matches source proportions
var CAPY = 790;
var NLx0 = 300, NLx1 = 940, NLw = NLx1 - NLx0;
var SERIF = '"Times New Roman", Georgia, serif';

var COL = {
  gray: '#d9d9d9', line: '#000',
  amber: '#e08a00', amberFill: '#ffe0a8',
  blue: '#2f6fb5', blueFill: '#bcd9f5', blueSoft: '#dceaf8',
  red: '#c02626', redFill: '#ffc9c9'
};

/* ────────── state ────────── */
var bsA = [.78, .17, .39, .26, .72, .94, .21, .12, .23, .68];
var bsView = {
  buckets: null, read: 0, mark: -1, hi: null, bad: {},
  concat: false, probe: 0.94, nl: false          // nl: number-line overlay (off by default)
};
var bsCount = 10;
var bsFrames = [], bsIdx = -1, bsPlaying = false, bsTimer = null, bsFps = 4, bsBad = {}, bsReplay = false;

function bsFmt(x) { var s = Number(x).toFixed(2); return s.charAt(0) === '0' ? s.slice(1) : s; }
function cmpNum(a, b) { return a - b; }
function emptyBuckets() { var o = []; for (var i = 0; i < 10; i++) o.push([]); return o; }

function distributeState(count) {
  var bs = emptyBuckets(), last = null;
  for (var i = 0; i < count && i < bsA.length; i++) {
    var x = bsA[i], b = Math.max(0, Math.min(9, Math.floor(10 * x))), k = 0;
    while (k < bs[b].length && bs[b][k] < x) k++;
    bs[b].splice(k, 0, x);
    last = { b: b, k: k };
  }
  return { buckets: bs, last: last };
}

/* ────────── drawing helpers ────────── */
function bsLabel(g, str, x, y, size, o) {
  o = o || {};
  var t = g.plain(String(str));
  t.font({ family: SERIF, size: size });
  if (o.italic) t.font({ style: 'italic' });
  t.attr({
    x: x, y: y, 'text-anchor': o.anchor || 'middle',
    'dominant-baseline': 'central', fill: o.fill || '#111', 'pointer-events': 'none'
  });
  if (o.halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
  return t;
}
function bsArrow(g, x1, y, x2, color, w, hs) {
  color = color || '#000'; w = w || 2.6; hs = hs || 12;
  g.line(x1, y, x2 - hs * 0.75, y).stroke({ color: color, width: w });
  g.polygon([[x2, y], [x2 - hs, y - hs * 0.55], [x2 - hs, y + hs * 0.55]]).fill(color);
}
function hook(el, tip, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', hideTooltip);
  el.on('click', function () { showPopup(title, body); });
}

/* ────────── static layer (headers + panel captions) ────────── */
bsLabel(gStatic, 'A', LA.x + LA.w / 2, 30, 34, { italic: true });
bsLabel(gStatic, 'B', LB.x + LB.w / 2, 30, 34, { italic: true });
