bsLabel(gStatic, '(b)', 640, CAPY, 32);

/* ────────── main render ────────── */
function bsRender() {
  gMain.clear();
  var v = bsView, n = bsA.length;

  /* --- dynamic canvas height: overlays extend it, default matches the source --- */
  var NLy = 900, TICKy = NLy + 30;
  var concatY = v.nl ? 1000 : 860;
  var H = BASE_H;
  if (v.nl) H = 965;
  if (v.concat) H = concatY + 74;
  bsDraw.viewbox(0, 0, VBW, H);

  var chA = Math.min(CH, 680 / Math.max(10, n));

  /* ---- panel (a) ---- */
  for (var i = 0; i < n; i++) {
    var y = Y0 + i * chA, hot = (v.read === i + 1);
    var r = gMain.rect(LA.w, chA).move(LA.x, y)
      .fill(hot ? COL.amberFill : COL.gray)
      .stroke({ color: hot ? COL.amber : COL.line, width: hot ? 3.5 : 2 });
    bsLabel(gMain, bsFmt(bsA[i]), LA.x + LA.w / 2, y + chA / 2, Math.min(30, chA * 0.46));
    bsLabel(gMain, String(i + 1), LA.x - 16, y + chA / 2, Math.min(26, chA * 0.40), { anchor: 'end' });
    (function (idx) {
      var x = bsA[idx], b = Math.floor(10 * x);
      hook(r, 'A[' + (idx + 1) + '] = ' + bsFmt(x) + '  →  ⌊10 × ' + bsFmt(x) + '⌋ = bucket ' + b,
        'A[' + (idx + 1) + '] = ' + bsFmt(x),
        'Bucket sort reads this value once and computes ⌊10·x⌋ = ' + b + '. That single arithmetic step decides the coarse position of the value in the final order — no comparison with any other element of A is needed.');
    })(i);
  }

  /* ---- chain layout (nodes sized to the bucket-cell row, as in the source) ---- */
  var maxLen = 1, b;
  for (b = 0; b < 10; b++) maxLen = Math.max(maxLen, v.buckets[b].length);
  var startX = 452, avail = 1044 - startX;
  var unit = Math.min(196, avail / Math.max(1, maxLen));
  var total = Math.min(116, unit * 0.62);
  var NWv = total * 0.52, NWp = total * 0.48;
  var NH = Math.max(18, Math.min(CH * 0.68, total * 0.40));
  var spacing = unit;

  var probeB = Math.max(0, Math.min(9, Math.floor(10 * v.probe)));

  /* ---- panel (b) ---- */
  for (b = 0; b < 10; b++) {
    var by = Y0 + b * CH, cy = by + CH / 2;
    var marked = (v.mark === b);
    var cell = gMain.rect(LB.w, CH).move(LB.x, by)
      .fill(marked ? COL.blueFill : COL.gray)
      .stroke({ color: marked ? COL.blue : COL.line, width: marked ? 3.5 : 2 });
    bsLabel(gMain, String(b), LB.x - 16, cy, 26, { anchor: 'end' });
    if (v.nl && probeB === b) {
      gMain.rect(LB.w + 14, CH + 10).move(LB.x - 7, by - 5).fill('none')
        .stroke({ color: COL.blue, width: 2, dasharray: '5,4' });
    }
    (function (bb) {
      var list = v.buckets[bb].map(bsFmt).join(' → ') || 'NIL (empty)';
      hook(cell, 'B[' + bb + ']  interval [' + (bb / 10).toFixed(1) + ', ' + ((bb + 1) / 10).toFixed(1) + ')   chain: ' + list,
        'Bucket ' + bb,
        'B[' + bb + '] is the head of a linked list holding every x with ⌊10·x⌋ = ' + bb + ', i.e. x in the half-open interval [' + (bb / 10).toFixed(1) + ', ' + ((bb + 1) / 10).toFixed(1) + '). Its current chain is ' + list + '. Because buckets are visited in index order at the end, everything here comes after every value in buckets 0…' + (bb - 1) + ' and before everything in buckets ' + (bb + 1) + '…9.');
    })(b);

    var list = v.buckets[b];
    if (!list.length) {
      gMain.line(LB.x + 14, by + CH - 14, LB.x + LB.w - 14, by + 14).stroke({ color: COL.line, width: 2.4 });
      continue;
    }
    gMain.line(LB.x + 22, cy, LB.x + LB.w, cy).stroke({ color: COL.line, width: 2.6 });
    bsArrow(gMain, LB.x + LB.w, cy, startX, COL.line, 2.6, 13);

    for (var k = 0; k < list.length; k++) {
      var nx = startX + k * spacing, ny = cy - NH / 2;
      var isHi = v.hi && v.hi.b === b && v.hi.k === k;
      var isBad = !!v.bad[b + ':' + k];
      var fill = isBad ? COL.redFill : (isHi ? COL.blueFill : COL.gray);
      var strk = isBad ? COL.red : (isHi ? COL.blue : COL.line);
      var box = gMain.rect(NWv + NWp, NH).move(nx, ny)
        .fill(fill).stroke({ color: strk, width: (isHi || isBad) ? 3.2 : 2 });
      gMain.line(nx + NWv, ny, nx + NWv, ny + NH).stroke({ color: strk, width: 2 });
      bsLabel(gMain, bsFmt(list[k]), nx + NWv / 2, cy, Math.max(10, NWv * 0.45));
      if (k < list.length - 1) {
        gMain.line(nx + NWv + NWp * 0.18, cy, nx + NWv + NWp * 0.82, cy).stroke({ color: COL.line, width: 2.6 });
        bsArrow(gMain, nx + NWv + NWp, cy, nx + spacing, COL.line, 2.6,
          Math.max(7, Math.min(13, (spacing - NWv - NWp) * 0.5)));
      } else {
        gMain.line(nx + NWv + NWp * 0.16, ny + NH - NH * 0.18, nx + NWv + NWp * 0.84, ny + NH * 0.18)
          .stroke({ color: COL.line, width: 2.3 });
      }
      (function (bb, kk, val, badFlag) {
        hook(box, 'node ' + kk + ' of bucket ' + bb + ' = ' + bsFmt(val) + (badFlag ? '  ✗ violates the invariant' : ''),
          'Record ' + bsFmt(val),
          'A two-field record: the left field stores the key ' + bsFmt(val) + ', the right field stores the next pointer (a diagonal slash means NIL). It sits at position ' + kk + ' of bucket ' + bb + ' because insertion walks the tiny chain and splices the node where the list stays increasing.' + (badFlag ? ' This node breaks the invariant — it is either in the wrong bucket or out of order in its chain.' : ''));
      })(b, k, list[k], isBad);
    }
  }

  /* ---- number-line overlay (only after the student probes / runs code) ---- */
  if (v.nl) {
    if (v.mark >= 0 && v.mark !== probeB) {
      gMain.rect(NLw / 10, 30).move(NLx0 + v.mark * NLw / 10, NLy - 15).fill(COL.blueSoft);
    }
    gMain.rect(NLw / 10, 30).move(NLx0 + probeB * NLw / 10, NLy - 15)
      .fill(COL.blueFill).stroke({ color: COL.blue, width: 1.8, dasharray: '4,3' });
    gMain.line(NLx0, NLy, NLx1, NLy).stroke({ color: '#444', width: 2.2 });
    for (var t = 0; t <= 10; t++) {
      var tx = NLx0 + t * NLw / 10;
      gMain.line(tx, NLy - 11, tx, NLy + 11).stroke({ color: '#444', width: 1.8 });
      if (t < 10) bsLabel(gMain, String(t), tx + NLw / 20, TICKy, 22, { fill: '#555', halo: true });
    }
    bsLabel(gMain, '0', NLx0, TICKy, 24, { fill: '#222', halo: true });
    bsLabel(gMain, '1', NLx1, TICKy, 24, { fill: '#222', halo: true });

    var px = NLx0 + v.probe * NLw;
    gMain.line(px, NLy - 30, px, NLy + 15).stroke({ color: COL.blue, width: 2.6 });
    gMain.polygon([[px, NLy - 14], [px - 8, NLy - 30], [px + 8, NLy - 30]]).fill(COL.blue);

    /* caption sits well above the arrow, on its own plate → never touches the digits */
    var capTxt = 'x = ' + bsFmt(v.probe) + '   →   ⌊10x⌋ = ' + probeB;
    var capW = 300, capH = 36;
    var lx = Math.max(NLx0 + capW / 2, Math.min(NLx1 - capW / 2, px));
    var capCy = NLy - 58;
    gMain.rect(capW, capH).move(lx - capW / 2, capCy - capH / 2).radius(5)
      .fill('#ffffff').opacity(0.94).stroke({ color: COL.blue, width: 1.4 });
    bsLabel(gMain, capTxt, lx, capCy, 24, { fill: COL.blue });

    var nlHit = gMain.rect(NLw, 74).move(NLx0, NLy - 30).fill('#fff').opacity(0);
    hook(nlHit, 'each interval is half-open: [b/10, (b+1)/10)',
      'The half-open partition',
      '⌊10·x⌋ cuts [0,1) into ten intervals [b/10, (b+1)/10). The left endpoint belongs to the bucket, the right endpoint belongs to the next one — that is why 0.9 through 0.999 all land in bucket 9 and .94 can never spill into a tenth bucket.');
  }

  /* ---- concatenated output ---- */
  if (v.concat) {
    var flat = [];
    for (b = 0; b < 10; b++) for (var q = 0; q < v.buckets[b].length; q++) flat.push({ v: v.buckets[b][q], b: b });
    if (flat.length) {
      var cw = Math.min(64, 640 / flat.length), ox = 300;
      bsLabel(gMain, 'B[0] ⧺ B[1] ⧺ … ⧺ B[9] :', ox - 10, concatY + 20, 22,
        { anchor: 'end', italic: true, fill: COL.blue });
      for (var m = 0; m < flat.length; m++) {
        var bad = (m > 0 && flat[m - 1].v > flat[m].v + 1e-12);
        var cr = gMain.rect(cw, 40).move(ox + m * cw, concatY)
          .fill(bad ? COL.redFill : COL.blueFill)
          .stroke({ color: bad ? COL.red : COL.blue, width: 1.8 });
        bsLabel(gMain, bsFmt(flat[m].v), ox + m * cw + cw / 2, concatY + 20, cw > 50 ? 22 : 16);
        (function (item, bad2) {
          hook(cr, bsFmt(item.v) + ' came from bucket ' + item.b + (bad2 ? ' — out of order!' : ''),
            'Concatenation', 'Walking buckets 0…9 head-to-tail emits ' + bsFmt(item.v) + ' here. No comparison is ever made between elements of different buckets: the index ⌊10x⌋ already ordered them.');
        })(flat[m], bad);
      }
    }
  }
}

