/* ────────── interaction: distribution pass ────────── */
function setDistrib(count, showLast) {
  bsReplay = false; pbStop();
  bsCount = Math.max(0, Math.min(bsA.length, count));
  var d = distributeState(bsCount);
  bsView.buckets = d.buckets; bsView.bad = {};
  if (showLast && d.last) { bsView.read = bsCount; bsView.mark = d.last.b; bsView.hi = d.last; }
  else { bsView.read = 0; bsView.mark = -1; bsView.hi = null; }
  var st = bsCount === 0 ? 'idle' : (bsCount >= bsA.length ? 'done' : 'running');
  var el = document.getElementById('distributeStepVal');
  if (el) el.textContent = st + ' — ' + bsCount + ' of ' + bsA.length + ' placed';
  bsRender();
}
function trigger_distributeReset() { setDistrib(0, false); }
function trigger_distributeStep() { setDistrib(bsCount + 1, true); }
function trigger_distributeRun() { setDistrib(bsA.length, false); }

