    st: { count: 10, probe: 0.94, concat: false, read: 0, mark: 9, hi: null, nl: true }
  },
  {
    title: 'Concatenate in index order',
    narration: 'All ten values are distributed; reading buckets 0 through 9 head-to-tail gives .12 .17 .21 .23 .26 .39 .68 .72 .78 .94 — the sorted output, with no comparison between buckets ever needed.',
    st: { count: 10, probe: 0.5, concat: true, read: 0, mark: -1, hi: null, nl: false }
  }
];
var bsStep = 0;

function applyStep(i) {
  bsStep = Math.max(0, Math.min(bsSteps.length - 1, i));
  var s = bsSteps[bsStep], st = s.st;
  bsReplay = false; pbStop();
  bsA = [.78, .17, .39, .26, .72, .94, .21, .12, .23, .68];
  bsCount = st.count;
  var d = distributeState(bsCount);
  bsView.buckets = d.buckets; bsView.bad = {};
  bsView.read = st.read; bsView.mark = st.mark; bsView.hi = st.hi;
  bsView.probe = st.probe; bsView.concat = st.concat; bsView.nl = st.nl;

  var pi = document.getElementById('probeValueInput');
  if (pi) { pi.value = st.probe; document.getElementById('probeValueVal').value = st.probe.toFixed(3); }
  var ci = document.getElementById('concatInput'); if (ci) ci.checked = st.concat;
  var ds = document.getElementById('distributeStepVal');
  if (ds) ds.textContent = (bsCount === 0 ? 'idle' : (bsCount >= bsA.length ? 'done' : 'running')) +
    ' — ' + bsCount + ' of ' + bsA.length + ' placed';
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = 'Step ' + (bsStep + 1) + '/' + bsSteps.length + ' · ' + s.title;
  bsRender();
}
function nextStep() { applyStep(bsStep + 1); }
function prevStep() { applyStep(bsStep - 1); }

/* ────────── code workbench ────────── */
var SAMPLES = {
  sample: 'function bucketSort(A, B) {\n  const n = 10;\n  for (let i = 1; i <= n; i++) {\n    const x = read(i);\n    const b = Math.floor(n * x);   // half-open bucket [b/10, (b+1)/10)\n    mark(b);\n    // walk the chain to find the sorted insertion point\n    let k = 0;\n    while (k < listLength(b) && nodeAt(b, k) < x) {\n      k++;\n    }\n    insertAt(b, k, x);\n    note(\'placed \' + x + \' at position \' + k + \' of bucket \' + b);\n  }\n}',
  buggy: 'function bucketSort(A, B) {\n  const n = 10;\n  for (let i = 1; i <= n; i++) {\n    const x = read(i);\n    // BUG 1: round() instead of floor() -- .78 lands in bucket 8, not 7\n    const b = Math.round(n * x);\n    mark(b);\n    // BUG 2: always appends at the tail, so a chain can come out unsorted (.17 before .12)\n    insertAt(b, listLength(b), x);\n  }\n}',
  starter: 'function bucketSort(A, B) {\n  const n = 10;\n  for (let i = 1; i <= n; i++) {\n    const x = read(i);\n    // 1. which bucket?   b = ?\n    // 2. where inside the chain?  use listLength(b) / nodeAt(b, k)\n    // 3. insertAt(b, k, x)\n  }\n}'
};
function loadSample(which) {
  document.getElementById('bucketSortEditorCode').value = SAMPLES[which];
  ['Sample', 'Buggy', 'Starter'].forEach(function (nm) {
    var el = document.getElementById('tab' + nm);
    if (el) el.className = (nm.toLowerCase() === which) ? 'active' : '';
  });
}

var WORKER_SRC = [
  'self.onmessage = function(ev){',
  '  var A = ev.data.A, code = ev.data.code, nB = 10;',
  '  var frames = [], buckets = [];',
  '  for (var i=0;i<nB;i++) buckets.push([]);',
  '  var ops = 0, t0 = Date.now(), lastRead = 0, lastMark = -1;',
  '  function fmt(x){ var s = Number(x).toFixed(2); return s.charAt(0)==="0" ? s.slice(1) : s; }',
  '  function snap(){ var o=[]; for(var i=0;i<nB;i++) o.push(buckets[i].slice()); return o; }',
  '  function guard(){',
  '    ops++;',
  '    if (ops > 4000) throw new Error("Operation cap exceeded (4000 API calls) - possible infinite loop.");',
  '    if (frames.length > 800) throw new Error("Frame cap exceeded (800 frames).");',
  '    if (Date.now() - t0 > 1500) throw new Error("Time limit exceeded (1.5 s).");',
  '  }',
  '  function push(kind, ind, msg){ frames.push({kind:kind, state:snap(), indices:ind||null, message:msg, read:lastRead, mark:lastMark}); }',
  '  function chkB(b, who){ b = Math.trunc(Number(b)); if(!(b>=0 && b<nB)) throw new Error(who+"("+b+"): bucket index must be 0.."+(nB-1)); return b; }',
  '  var read = function(i){ guard(); i = Math.trunc(Number(i));',
  '    if(!(i>=1 && i<=A.length)) throw new Error("read("+i+"): A is 1-indexed, valid range 1.."+A.length);',
  '    lastRead = i; push("read", {a:i}, "read A["+i+"] = "+fmt(A[i-1])); return A[i-1]; };',
  '  var listLength = function(b){ b = chkB(b,"listLength"); guard();',
  '    push("probe", {b:b}, "listLength("+b+") = "+buckets[b].length); return buckets[b].length; };',
  '  var nodeAt = function(b,k){ b = chkB(b,"nodeAt"); guard(); k = Math.trunc(Number(k));',
  '    if(!(k>=0 && k<buckets[b].length)) throw new Error("nodeAt("+b+","+k+"): bucket "+b+" has "+buckets[b].length+" node(s)");',
  '    push("compare", {b:b,k:k}, "nodeAt("+b+","+k+") = "+fmt(buckets[b][k])); return buckets[b][k]; };',
  '  var insertAt = function(b,k,x){ b = chkB(b,"insertAt"); guard(); k = Math.trunc(Number(k)); x = Number(x);',
  '    if(!isFinite(x)) throw new Error("insertAt("+b+","+k+",x): x must be a number");',
  '    if(!(k>=0 && k<=buckets[b].length)) throw new Error("insertAt("+b+","+k+"): position must be 0.."+buckets[b].length);',
  '    buckets[b].splice(k,0,x); lastMark = b;',
  '    push("insert", {b:b,k:k}, "insertAt(bucket "+b+", pos "+k+", "+fmt(x)+")"); return null; };',
  '  var mark = function(b){ b = chkB(b,"mark"); guard(); lastMark = b;',
  '    push("mark", {b:b}, "mark bucket "+b+"  -> interval ["+(b/10).toFixed(1)+", "+((b+1)/10).toFixed(1)+")"); return null; };',
  '  var note = function(t){ guard(); push("note", null, String(t)); return null; };',
  '  var err = null;',
  '  try {',
  '    var factory = new Function("read","listLength","nodeAt","insertAt","mark","note",',
  '      "\\"use strict\\";" + code + "\\n; return (typeof bucketSort === \\"function\\") ? bucketSort : null;");',
  '    var fn = factory(read,listLength,nodeAt,insertAt,mark,note);',
  '    if(!fn) throw new Error("No function named bucketSort(A, B) was found - check the entry point name.");',
  '    fn(A.slice(), {});',
  '  } catch(e){ err = (e && e.message) ? e.message : String(e); }',
  '  if (err) frames.push({kind:"error", state:snap(), indices:null, message:"ERROR: "+err, read:lastRead, mark:lastMark});',
  '  else frames.push({kind:"done", state:snap(), indices:null, message:"finished - "+frames.length+" operations recorded", read:0, mark:-1});',
  '  self.postMessage({frames:frames, error:err});',
  '};'
].join('\n');

function parseArray(str) {
  var parts = String(str).split(/[\s,;]+/), out = [];
  for (var i = 0; i < parts.length; i++) {
    if (!parts[i]) continue;
    var v = Number(parts[i]);
    if (!isFinite(v)) continue;
    if (v < 0) v = 0;
    if (v >= 1) v = 0.999;
    out.push(v);
  }
  return out;
}

function setStatus(txt, color) {
  var el = document.getElementById('runStatus');
  el.textContent = txt; el.style.color = color;
}

function bsCheck(buckets) {
  var bad = {}, problems = [], flat = [], b, k;
  for (b = 0; b < 10; b++) for (k = 0; k < buckets[b].length; k++) flat.push(buckets[b][k]);
  var a = bsA.slice().sort(cmpNum), g = flat.slice().sort(cmpNum);
  var msOk = a.length === g.length;
  if (msOk) for (var i = 0; i < a.length; i++) if (Math.abs(a[i] - g[i]) > 1e-9) { msOk = false; break; }
  if (!msOk) problems.push('B does not hold exactly the values of A (' + g.length + ' placed, ' + a.length + ' expected)');
  for (b = 0; b < 10; b++) {
    for (k = 0; k < buckets[b].length; k++) {
      var x = buckets[b][k];
      if (Math.floor(10 * x) !== b) {
        bad[b + ':' + k] = 1;
        problems.push(bsFmt(x) + ' sits in bucket ' + b + ' but ⌊10x⌋ = ' + Math.floor(10 * x));
      }
      if (k > 0 && buckets[b][k - 1] > x + 1e-12) {
        bad[b + ':' + k] = 1; bad[b + ':' + (k - 1)] = 1;
        problems.push('bucket ' + b + ' chain out of order: ' + bsFmt(buckets[b][k - 1]) + ' before ' + bsFmt(x));
      }
    }
  }
  return { ok: msOk && problems.length === 0, bad: bad, problems: problems };
}

function runCode() {
  var codeEl = document.getElementById('bucketSortEditorCode');
  var arr = parseArray(document.getElementById('bucketSortEditorInput').value);
  if (!arr.length) { setStatus('✗ input array is empty / unparsable', COL.red); return; }
  bsA = arr;
  pbStop();
  bsReplay = true; bsFrames = []; bsIdx = -1; bsBad = {};
  bsView.buckets = emptyBuckets(); bsView.read = 0; bsView.mark = -1; bsView.hi = null; bsView.bad = {};
  bsView.nl = true;                       // mark(b) shades an interval, so show the line
  bsRender();
  setStatus('running…', '#8a6d00');
  document.getElementById('runBtn').disabled = true;

  var url = URL.createObjectURL(new Blob([WORKER_SRC], { type: 'text/javascript' }));
  var w = new Worker(url);
  var done = false;
  function cleanup() { try { w.terminate(); } catch (e) { } URL.revokeObjectURL(url); document.getElementById('runBtn').disabled = false; }
  var timer = setTimeout(function () {
    if (done) return; done = true; cleanup();
    finishRun({ frames: [{ kind: 'error', state: emptyBuckets(), indices: null, read: 0, mark: -1, message: 'ERROR: timed out — the worker did not finish within 2 s (infinite loop?)' }], error: 'timeout' });
  }, 2000);
  w.onerror = function (e) {
    if (done) return; done = true; clearTimeout(timer); cleanup();
    finishRun({ frames: [{ kind: 'error', state: emptyBuckets(), indices: null, read: 0, mark: -1, message: 'ERROR: ' + (e.message || 'worker failed') }], error: 'worker' });
  };
  w.onmessage = function (e) {
    if (done) return; done = true; clearTimeout(timer); cleanup();
    finishRun(e.data);
  };
  w.postMessage({ A: bsA.slice(), code: codeEl.value });
}

function finishRun(data) {
  bsFrames = data.frames || [];
  if (!bsFrames.length) bsFrames = [{ kind: 'error', state: emptyBuckets(), indices: null, read: 0, mark: -1, message: 'ERROR: no frames recorded — did your code call any API op?' }];
  var last = bsFrames[bsFrames.length - 1];
  if (data.error) {
    bsBad = {};
    setStatus('✗ error — see caption', COL.red);
  } else {
    var res = bsCheck(last.state);
    bsBad = res.bad;
    if (res.ok) setStatus('✓ correct — buckets concatenate to sorted order', '#1a7a34');
    else setStatus('✗ wrong: ' + (res.problems[0] || 'invariant broken') + (res.problems.length > 1 ? ' (+' + (res.problems.length - 1) + ' more, click)' : ''), COL.red);
    document.getElementById('runStatus').onclick = function () {
      showPopup(res.ok ? 'Success check passed' : 'Success check failed',
        res.ok ? 'Every value of A appears exactly once, each x lies in bucket ⌊10x⌋, and every chain is increasing — so concatenating buckets 0…9 yields the fully sorted sequence.'
          : 'Problems found:\n• ' + res.problems.slice(0, 8).join('\n• '));
    };
  }
  bsReplay = true;
  bsIdx = 0;
  showFrame(0);
  bsPlay();
}

function frameKindTag(k) {
  return { read: 'read', probe: 'len', compare: 'cmp', insert: 'INSERT', mark: 'mark', note: 'note', done: 'done', error: 'ERR' }[k] || k;
}

function showFrame(i) {
  if (!bsFrames.length) return;
  bsIdx = Math.max(0, Math.min(bsFrames.length - 1, i));
  var f = bsFrames[bsIdx];
  bsReplay = true;
  bsView.buckets = f.state;
  bsView.read = f.read;
  bsView.mark = f.mark;
  bsView.hi = (f.indices && f.indices.b != null && f.indices.k != null) ? { b: f.indices.b, k: f.indices.k } : null;
  bsView.bad = (bsIdx === bsFrames.length - 1) ? bsBad : {};
  document.getElementById('frameCounter').textContent = (bsIdx + 1) + ' / ' + bsFrames.length;
  document.getElementById('frameCaption').textContent = f.message;
  var lines = [], start = Math.max(0, bsIdx - 25);
  for (var j = start; j <= bsIdx; j++) {
    lines.push((j === bsIdx ? '▸ ' : '  ') + (j + 1) + '  [' + frameKindTag(bsFrames[j].kind) + '] ' + bsFrames[j].message);
  }
  var lg = document.getElementById('runLog');
  lg.textContent = lines.join('\n');
  lg.scrollTop = lg.scrollHeight;
  bsRender();
}
function pbFirst() { pbStop(); showFrame(0); }
function pbPrev() { pbStop(); showFrame(bsIdx - 1); }
function pbNext() { pbStop(); showFrame(bsIdx + 1); }
function pbStop() {
  if (bsTimer) { clearInterval(bsTimer); bsTimer = null; }
  bsPlaying = false;
  var b = document.getElementById('pbPlayBtn'); if (b) b.textContent = '▶';
}
function pbPlay() {
  if (!bsFrames.length) return;
  if (bsPlaying) { pbStop(); return; }
  if (bsIdx >= bsFrames.length - 1) bsIdx = -1;
  bsPlaying = true;
  document.getElementById('pbPlayBtn').textContent = '⏸';
  bsTimer = setInterval(function () {
    if (bsIdx >= bsFrames.length - 1) { pbStop(); return; }
    showFrame(bsIdx + 1);
  }, 1000 / bsFps);
}
function setSpeed(v) {
  bsFps = Math.max(1, v);
  if (bsPlaying) { clearInterval(bsTimer); bsTimer = setInterval(function () { if (bsIdx >= bsFrames.length - 1) { pbStop(); return; } showFrame(bsIdx + 1); }, 1000 / bsFps); }
}

